import React, { useEffect, useState } from 'react';
import NavBar from '../Components/NavBar';

export default function Announcements() {
  const [ads, setAds] = useState([]);
  const [selectedAd, setSelectedAd] = useState(null);

  useEffect(() => {
    const fetchAds = async () => {
      try {
        const response = await fetch('http://localhost:5000/advertisements');
        if (response.ok) {
          const data = await response.json();
          setAds(data);
        }
      } catch (error) {
        console.error('Failed to fetch advertisements:', error);
      }
    };
    fetchAds();
  }, []);

  return (
    <div>
      <NavBar />
      <div style={{ padding: '20px' }}>
        <h2>Advertisements</h2>
        {ads.length === 0 && <p>No advertisements to show.</p>}
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: '15px' }}>
                {ads.map(ad => (
                <div key={ad.id} style={{ cursor: 'pointer', margin: '10px' }} onClick={() => setSelectedAd(ad)}>
                    {ad.link ? (
                    <a href={ad.link} target="_blank" rel="noopener noreferrer">
                        <img src={ad.poster} alt={ad.title} style={{ width: '150px', height: '150px', objectFit: 'cover' }} />
                    </a>
                    ) : (
                    <img src={ad.poster} alt={ad.title} style={{ width: '150px', height: '150px', objectFit: 'cover' }} />
                    )}
                </div>
                ))}

        </div>
        {selectedAd && (
          <div style={{
            position: 'fixed',
            top: 0, left: 0, right: 0, bottom: 0,
            backgroundColor: 'rgba(0,0,0,0.5)',
            display: 'flex', justifyContent: 'center', alignItems: 'center',
            zIndex: 9999,
          }}
            onClick={() => setSelectedAd(null)}
          >
            <div style={{
              backgroundColor: 'white', padding: '20px',
              borderRadius: '8px', maxWidth: '500px', maxHeight: '80vh',
              overflowY: 'auto',
              boxShadow: '0 0 10px #333',
              position: 'relative'
            }}
              onClick={e => e.stopPropagation()}
            >
              <h3>{selectedAd.title}</h3>
              <img src={selectedAd.poster} alt={selectedAd.title} style={{ maxWidth: '100%', maxHeight: '300px', objectFit: 'contain' }} />
              <p>{selectedAd.content}</p>
              {selectedAd.link && <a href={selectedAd.link} target="_blank" rel="noopener noreferrer">Learn more</a>}
              <button onClick={() => setSelectedAd(null)} style={{ marginTop: '10px' }}>Close</button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}
